_CORE_SRC = '# Action format: "{from_node: {to_node: count, ...}}".\n# Payout: serving_p = min(units_p at the node, SERVE_LIMIT);\n# capacity_p = serving_p * UNIT_CAPACITY;\n# filled_p = capacity_p * orders / max(total_capacity, orders).\n# Every unit away from its own base pays "1.0 + 0.5 * hops" per turn.\n# Moves use start-of-turn units, cross one link, and precede the payout.\n\nimport heapq\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 90\nUNIT_CAPACITY = 4\nSERVE_LIMIT = 6\n\n\ndef filled(own, rival, orders):\n    """The specification\'s revenue formula, including its zero case."""\n    capacity = min(own, SERVE_LIMIT) * UNIT_CAPACITY\n    other = min(rival, SERVE_LIMIT) * UNIT_CAPACITY\n    denominator = max(capacity + other, orders)\n    return capacity * orders / denominator if denominator > 0 else 0.0\n\n\ndef revenue_margin(own, rival, orders):\n    return filled(own, rival, orders) - filled(rival, own, orders)\n\n\ndef preprocess_map(graph, base):\n    n = int(graph["nodes"])\n    adjacency = [[] for _ in range(n)]\n    for u, v in graph["links"]:\n        adjacency[u].append(v)\n        adjacency[v].append(u)\n    for neighbors in adjacency:\n        neighbors.sort()\n\n    distances = []\n    for source in range(n):\n        row = [-1] * n\n        row[source] = 0\n        queue = deque([source])\n        while queue:\n            u = queue.popleft()\n            for v in adjacency[u]:\n                if row[v] < 0:\n                    row[v] = row[u] + 1\n                    queue.append(v)\n        distances.append(row)\n\n    upkeep = [0.0 if v == base else 1.0 + 0.5 * distances[base][v]\n              for v in range(n)]\n    next_hop = [[s] * n for s in range(n)]\n    for s in range(n):\n        for target in range(n):\n            if s != target and distances[s][target] > 0:\n                # Among shortest routes prefer the cheaper intermediate node.\n                next_hop[s][target] = min(\n                    (v for v in adjacency[s]\n                     if distances[v][target] == distances[s][target] - 1),\n                    key=lambda v: (upkeep[v], v),\n                )\n    return adjacency, distances, next_hop, upkeep\n\n\ndef legal_action(have, want, adjacency, distances, next_hop):\n    """Closest-first surplus matching; validate against start-of-turn stock."""\n    n = len(have)\n    surplus = [max(0, have[v] - want[v]) for v in range(n)]\n    deficit = [max(0, want[v] - have[v]) for v in range(n)]\n    pairs = sorted(\n        (distances[s][t], s, t)\n        for s in range(n) if surplus[s]\n        for t in range(n) if deficit[t] and distances[s][t] > 0\n    )\n    proposed = {}\n    for _, source, target in pairs:\n        count = min(surplus[source], deficit[target])\n        if count <= 0:\n            continue\n        surplus[source] -= count\n        deficit[target] -= count\n        hop = next_hop[source][target]\n        key = (source, hop)\n        proposed[key] = proposed.get(key, 0) + count\n\n    available = list(have)\n    action = {}\n    for (source, target), count in sorted(proposed.items()):\n        if not (0 <= source < n and 0 <= target < n):\n            continue\n        if target not in adjacency[source]:\n            continue\n        count = min(int(count), int(available[source]))\n        if count > 0:\n            action.setdefault(int(source), {})[int(target)] = int(count)\n            available[source] -= count\n    return action\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_data = None\n        self.previous_target = None\n        self.bad_feedback = 0\n\n    def plan(self, obs, deadline):\n        adjacency, distances, next_hop, upkeep = self.map_data\n        have = list(obs["you"]["units"])\n        rival = list(obs["rival"]["units"])\n        base = int(obs["you"]["base"])\n        n = len(have)\n        left = max(0, N_TURNS - int(obs["turn"]))\n        if left == 0:\n            return have\n\n        horizon = min(12, left)\n        weights = [0.94 ** k for k in range(horizon)]\n        forecast = obs.get("orders", [])\n        if not forecast:\n            return have\n\n        # Beyond the exact window use a gently conservative last forecast.\n        demand = []\n        for k in range(horizon):\n            row = forecast[min(k, len(forecast) - 1)]\n            scale = 1.0 if k < len(forecast) else 0.96\n            demand.append([max(0.0, float(x)) * scale for x in row])\n\n        sources = [s for s in range(n) if have[s] > 0]\n        remaining = list(have)\n        want = [0] * n\n\n        # Integrated endpoint marginal values indexed by arrival turn and count.\n        marginal = []\n        for v in range(n):\n            table = [[0.0] * SERVE_LIMIT for _ in range(horizon + 1)]\n            for k in range(horizon - 1, -1, -1):\n                d = demand[k][v]\n                for count in range(SERVE_LIMIT):\n                    gain = (revenue_margin(count + 1, rival[v], d)\n                            - revenue_margin(count, rival[v], d))\n                    table[k][count] = table[k + 1][count] + weights[k] * gain\n            marginal.append(table)\n\n        # A trip pays upkeep at every intermediate position, including the\n        # destination on its arrival turn. No speculative transit revenue.\n        trip_cost = {}\n        arrival = {}\n        for source in sources:\n            for target in range(n):\n                position = source\n                cost = 0.0\n                for k in range(horizon):\n                    if position != target:\n                        position = next_hop[position][target]\n                    cost += weights[k] * upkeep[position]\n                trip_cost[source, target] = cost\n                arrival[source, target] = max(0, distances[source][target] - 1)\n\n        old = self.previous_target\n        heap = []\n\n        def value(source, target, count):\n            if target == base or count >= SERVE_LIMIT:\n                return -float("inf")\n            delay = arrival[source, target]\n            if delay >= horizon:\n                return -float("inf")\n            # Returning home is the baseline, not magically disappearing.\n            gain = (marginal[target][delay][count]\n                    - trip_cost[source, target] + trip_cost[source, base])\n            # A small, bounded switching threshold preserves useful targets.\n            if old is not None and count < old[target]:\n                gain += 0.45\n            if source == target:\n                gain += 0.15\n            return gain\n\n        for source in sources:\n            for target in range(n):\n                if target == base:\n                    continue\n                score = value(source, target, 0)\n                if score > 0:\n                    heapq.heappush(heap, (-score, source, target, 0))\n\n        # Concavity makes lazy marginal updates safe. All unassigned units\n        # retain their legal, free terminal target at home.\n        iterations = 0\n        while heap:\n            if iterations % 16 == 0 and time.perf_counter() >= deadline:\n                break\n            iterations += 1\n            negative, source, target, version = heapq.heappop(heap)\n            if remaining[source] <= 0:\n                continue\n            count = want[target]\n            if version != count:\n                score = value(source, target, count)\n                if score > 0:\n                    heapq.heappush(heap, (-score, source, target, count))\n                continue\n            if negative >= 0:\n                break\n            want[target] += 1\n            remaining[source] -= 1\n            if remaining[source] > 0:\n                score = value(source, target, want[target])\n                if score > 0:\n                    heapq.heappush(\n                        heap, (-score, source, target, want[target])\n                    )\n\n        want[base] += sum(remaining)\n        return want\n\n    def act(self, obs):\n        started = time.perf_counter()\n        deadline = started + max(0.0, 0.6 * TIME_BUDGET)\n        if self.map_data is None:\n            self.map_data = preprocess_map(\n                obs["graph"], int(obs["you"]["base"])\n            )\n\n        feedback = obs.get("feedback", {})\n        if (not feedback.get("format_ok", True)\n                or feedback.get("rejected", 0) > 0):\n            self.bad_feedback += 1\n\n        have = list(obs["you"]["units"])\n        adjacency, distances, next_hop, _ = self.map_data\n        if self.bad_feedback >= 2:\n            # Conservative recovery still uses the same start-stock validator.\n            want = [0] * len(have)\n            want[int(obs["you"]["base"])] = sum(have)\n        else:\n            want = self.plan(obs, deadline)\n\n        self.previous_target = list(want)\n        return legal_action(have, want, adjacency, distances, next_hop)\n'
_CORE_CLASS = 'Strategy'
